    if (esxiFilters.advisoryId && !a.advisoryId.toLowerCase().includes(esxiFilters.advisoryId.toLowerCase())) return false;
    if (esxiFilters.title && !a.title.toLowerCase().includes(esxiFilters.title.toLowerCase())) return false;
